/* BIOS Boot Screen */
.bios-boot-screen {
  position: fixed;
  inset: 0;
  background: #000;
  color: #c0c0c0;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.6;
  z-index: 99999;
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}
.bios-boot-screen.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.bios-content {
  max-width: 800px;
}
.bios-line {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 0;
  animation: biosFadeIn 0.1s forwards;
}
.bios-line:nth-child(1) { animation-delay: 0.1s; }
.bios-line:nth-child(2) { animation-delay: 0.25s; }
.bios-line:nth-child(3) { animation-delay: 0.4s; }
